/* Database : shop */
SET NAMES utf8mb4;
SET @OLD_FOREIGN_KEY_CHECKS = @@FOREIGN_KEY_CHECKS, FOREIGN_KEY_CHECKS = 0;
SET @OLD_SQL_MODE = @@SQL_MODE, SQL_MODE = 'NO_AUTO_VALUE_ON_ZERO';

/* Routines */
SET @OLD_ROUTINE_SQL_MODE = @@SQL_MODE, SQL_MODE = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION';
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` FUNCTION `tax`(a decimal(10,2)) RETURNS decimal(10,2)
    DETERMINISTIC
    COMMENT '세금 10%'
BEGIN RETURN a * 0.1; END;;
DELIMITER ;
SET SQL_MODE = @OLD_ROUTINE_SQL_MODE;
SET @OLD_ROUTINE_SQL_MODE = @@SQL_MODE, SQL_MODE = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION';
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` FUNCTION `same_fn`(x int) RETURNS int
    NO SQL
    DETERMINISTIC
RETURN x + 1;;
DELIMITER ;
SET SQL_MODE = @OLD_ROUTINE_SQL_MODE;
SET @OLD_ROUTINE_SQL_MODE = @@SQL_MODE, SQL_MODE = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION';
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `mode_proc`()
BEGIN
  SELECT 1;
END;;
DELIMITER ;
SET SQL_MODE = @OLD_ROUTINE_SQL_MODE;
SET @OLD_ROUTINE_SQL_MODE = @@SQL_MODE, SQL_MODE = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION';
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `old_proc`(IN p_id int)
    MODIFIES SQL DATA
BEGIN UPDATE orders SET status = 'old;;' WHERE id = p_id; END;;
DELIMITER ;
SET SQL_MODE = @OLD_ROUTINE_SQL_MODE;

/* Table : orders */
CREATE TABLE `orders` (
  `id` int NOT NULL AUTO_INCREMENT,
  `amount` decimal(10,2) NOT NULL,
  `status` varchar(10) NOT NULL DEFAULT 'new',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


/* Table : order_tax */
CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `order_tax` AS select `orders`.`id` AS `id`,`tax`(`orders`.`amount`) AS `tax` from `orders`;


SET FOREIGN_KEY_CHECKS = @OLD_FOREIGN_KEY_CHECKS;
SET SQL_MODE = @OLD_SQL_MODE;
